package net.officefloor.hq.app.rollup;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.history.HistoryRecorder;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonSnapshot;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** When the sheet's today changes, records each person's due-total as it stood on the day being left, before the
 *  change takes effect (so before any period closes and before the change's rollup lines), and keeps it on the
 *  person as a snapshot of that day (recorded in its history on that day, so the sheet as of it shows it). */
public class AuditSnapshot {
    public void audit(@Val LocalDate today, @Val Sheet sheet, @Val Rollup before,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit, PersonRepository people,
            HistoryRecorder recorder) {
        if (today.equals(sheet.getToday())) {
            return;
        }
        before.dueTotals().forEach((id, due) -> people.findById(id).ifPresent(p -> {
            p.addSnapshot(new PersonSnapshot(sheet.getToday(), due));
            recorder.recordOn(p, sheet.getToday());
            people.save(p);
        }));
        before.snapshot(sheet.getId(), AuditUser.decode(user)).forEach(audit::record);
    }
}
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { countsLive, holdsOf, isOpen, useClaims, type Claim } from '../claims/claims';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, sumDue, useRates, type Rate } from './rates';

// A person's settled-total and open-total: the dues of their counted SETTLED claims (frozen figures, corrections
// included), and of their counted OPEN and PENDING claims (a deferred or retired-and-excluded one left out, as
// from the due-total), each added up skipping n/a. Together they make their due-total before the cap. The sheet's are
// everyone's added up (not trimmed).
export function splitOf(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): { settled: string; open: string } {
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, holdsOf([person]), today));
  const total = (of: Claim[]) => sumDue(of.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today)));
  return { settled: total(mine.filter((c) => c.status === 'SETTLED')), open: total(mine.filter(isOpen)) };
}

function useSplit() {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return (person: Person) => splitOf(person, claims.data ?? [], rates.data, today, settings.data);
}

function SplitHeader() {
  return (
    <>
      <th>Settled total</th>
      <th>Open total</th>
    </>
  );
}

function PersonSplit({ person }: { person: Person }) {
  const { settled, open } = useSplit()(person);
  return (
    <>
      <td data-testid="person-settled-total">{settled}</td>
      <td data-testid="person-open-total">{open}</td>
    </>
  );
}

function SplitTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const split = useSplit();
  if (!user || !sheet) return null;
  const each = (people.data ?? []).map(split);
  return (
    <p>
      Settled in total <strong data-testid="rollup-settled-total">{sumDue(each.map((s) => s.settled))}</strong>{' '}
      open in total <strong data-testid="rollup-open-total">{sumDue(each.map((s) => s.open))}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 15.7, Component: SplitHeader }),
  PersonCells.fill({ order: 15.7, Component: PersonSplit }),
  HomeMain.fill({ order: 31.5, Component: SplitTotal }),
];
import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { gradeOn, usePeople, type Person } from '../people/people';
import { useSettings, type Settings } from '../roles/roles';
import { chargedOf, sumDue, trimmedSum, useRates, type Rate } from '../rates/rates';
import { countsLive, holdsOf, isOverdue, useClaims, type Claim } from './claims';
import { useColumnShown } from '../people/columns';

// A person's overdue count and overdue-total: their counted claims that are overdue (OPEN or PENDING, due-by plus their grade's grace before the
// sheet's today; their unbound OPEN and PENDING claims dated within a hold of theirs do not count), and those claims' dues (with their late charge) added up, skipping n/a.
// The sheet's are everyone's added up (its overdue-total leaving out the highest and the lowest with three or more people).
export function overdueOf(person: Person, claims: Claim[], rates: Rate[] | undefined, today: string | undefined,
  settings: Settings | undefined): { count: number; total: string } {
  const held = holdsOf([person]);
  const mine = claims.filter((c) => c.personId === person.id && countsLive(c, held, today)
    && isOverdue(c, today, gradeOn(person, c.date), settings));
  return { count: mine.length, total: sumDue(mine.map((c) => chargedOf(c, rates, gradeOn(person, c.date), settings, today))) };
}

function useOverdue() {
  const claims = useClaims();
  const rates = useRates();
  const today = useSheetToday();
  const settings = useSettings();
  return (person: Person) => overdueOf(person, claims.data ?? [], rates.data, today, settings.data);
}

function OverdueHeader() {
  const count = useColumnShown('overdue-count');
  const total = useColumnShown('overdue-total');
  return (
    <>
      {count && <th>Overdue</th>}
      {total && <th>Overdue total</th>}
    </>
  );
}

function PersonOverdue({ person }: { person: Person }) {
  const { count, total } = useOverdue()(person);
  const countShown = useColumnShown('overdue-count');
  const totalShown = useColumnShown('overdue-total');
  return (
    <>
      {countShown && <td data-testid="person-overdue-count">{count}</td>}
      {totalShown && <td data-testid="person-overdue-total">{total}</td>}
    </>
  );
}

function OverdueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const overdue = useOverdue();
  if (!user || !sheet) return null;
  const each = (people.data ?? []).map(overdue);
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>{' '}
      totalling <strong data-testid="rollup-overdue-total">{trimmedSum(each.map((o) => o.total))}</strong>
    </p>
  );
}

export const contributions = [
  PeopleColumns.fill({ order: 16, Component: OverdueHeader }),
  PersonCells.fill({ order: 16, Component: PersonOverdue }),
  HomeMain.fill({ order: 32, Component: OverdueTotal }),
];

