            CAP = "cap", PROOF_THRESHOLD = "proof-threshold", NOTE_THRESHOLD = "note-threshold",
            REVIEW_THRESHOLD = "review-threshold";

    /** The key of the grace days: undated, a whole number of days (null: off). */
    public static final String GRACE_DAYS = "grace-days";

    /** The key of the escalation gap: undated, a whole number of days (null: off). */
    public static final String ESCALATE_AFTER = "escalate-after";

    /** The key of the review SLA: undated, a whole number of days (null: none). */
    public static final String REVIEW_SLA = "review-sla";
    public static final String SCORE_MID = "score-mid";
    public static final String SCORE_HIGH = "score-high";

    /** The key of the proof kinds: undated, a comma separated list of kinds (null: none). */
    public static final String PROOF_KINDS = "proof-kinds";

    /** The key of the default grade: undated, A, B or C (null: A). */
    public static final String DEFAULT_GRADE = "default-grade";

    /** The key of the pot: undated, an amount with two decimals (null: none). */
    public static final String POT = "pot";

    /** The key of the alert threshold: undated, an amount with two decimals (null: off). */
    public static final String ALERT_THRESHOLD = "alert-threshold";

    /** The key of the parent sheet: undated, a sheet's id (null: none). A grade with no rate in force on a date on
     *  this sheet takes the parent's, then the parent's parent's, up to three levels up (then, on a clone, those of the sheet it was cloned from). */
    public static final String PARENT = "parent";

    /** The key of the fiscal year start month: undated, a month 1 to 12 (null: 1). */
    public static final String FISCAL_START_MONTH = "fiscal-start-month";

    /** The key of the rounding mode: dated, half-up or half-even (null: none — a claim rounds by the policy date). */
    public static final String ROUNDING = "rounding", HALF_UP = "half-up", HALF_EVEN = "half-even";

    /** The keys of the undated dates, as the settings form names them. */
    public static final String POLICY_DATE = "policy-date", PERIOD_NUMBERING_FROM = "period-numbering-from",
            ENTRY_DATE = "entry-date";

    /** The setting key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    @Id
    private String id;

    /** The sheet's today: every date decision and default date uses it, never the real clock. */
    @Column(nullable = false)
    private LocalDate today;

    /** The dated settings: each setting that carries a figure — the clerk limit (a clerk settles a claim only when
     *  its due is at or below it), the floor (a claim's live due is at least it), the terms and each grade's own terms
        return days == null ? null : Integer.valueOf(days);
    }

    /** The escalation gap: reminding a claim whose previous reminder was at least this many days before the sheet's
     *  today escalates it (once per claim). Not dated; null when off. */
    public Integer getEscalateAfter() {
        String days = valueOn(ESCALATE_AFTER, today);
        return days == null ? null : Integer.valueOf(days);
    }

    /** The review SLA: a REVIEW claim whose review day plus this many days is before the sheet's today is late.
     *  Not dated; null when none. */
    public Integer getReviewSla() {
        String days = valueOn(REVIEW_SLA, today);
        return days == null ? null : Integer.valueOf(days);
    }

    /** A score threshold (score-mid or score-high): a whole number, possibly negative. Not dated; null when blank. */
    public Integer getScoreThreshold(String key) {
        String value = valueOn(key, today);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The proof kinds: while set, a claim whose due is above its proof threshold needs at least one proof of each
     *  to be settled or approved. Not dated; empty when none. */
    public List<String> getProofKinds() {
        String kinds = valueOn(PROOF_KINDS, today);
        return kinds == null || kinds.isBlank() ? List.of() : List.of(kinds.split(","));
    }

    /** The default grade: a person added by the quick-add bar, or by an import line with a blank grade, gets it.
     *  Not dated; A when none is set. */
    public String getDefaultGrade() {
        String grade = valueOn(DEFAULT_GRADE, today);
        return grade == null || grade.isBlank() ? "A" : grade;
    }

    /** The pot: shared out among the members of each balanced pool by their shares. Not dated; null when none. */
    public BigDecimal getPot() {
        return amountOn(POT, today);
    }

