import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { delegationsPath, delegationsQueryKey, useDelegations, type Delegation } from './roles';

// The sheet's delegations: each time a steward delegated the steward role to a user name for a from-date to a
// to-date, inclusive, by the sheet's today (blank: today), and the form that delegates. Anyone but a steward (by
// their own role), or a to-date before the from-date, is refused by the server and shows the form's error.
function Delegations() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const delegations = useDelegations();
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { user: string; from: string; to: string }) =>
      postJson<Delegation>(delegationsPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: delegationsQueryKey(sheet ?? '') });
      setName('');
      setFrom('');
      setTo('');
    },
  });
  const submit = useSubmitOnce(save);
# OfficeHQ

A full-stack office-management web application.

- **Front end:** React single-page app (TypeScript) with TanStack Router (file-based routes) and
  TanStack Query, built into `src/main/resources/static`.
- **Back end:** Spring Boot host with OfficeFloor REST endpoints, on an in-memory H2 database with
  Flyway migrations run on boot.

## Build and run

```
bin/build              # build the SPA and package one runnable jar
PORT=3000 bin/start    # start the app (serves the SPA + REST on $PORT)
bin/stop               # stop it
```

Readiness: `GET /actuator/health`.

## Tests

End-to-end tests use Playwright (in `e2e/`) and bind to `data-testid`:

```
bin/e2e                # build, start, run the specs in e2e/specs, then stop
```

